# find maximal rectangles where border is uniform color c (not bg=9)
def rect_candidates(M,bg):
    H,W=M.shape; res=[]
    for h in range(3,H+1):
        for w in range(3,W+1):
            for r in range(H-h+1):
                for c in range(W-w+1):
                    sub=M[r:r+h,c:c+w]
                    b=set(sub[0,:].tolist())|set(sub[-1,:].tolist())|set(sub[:,0].tolist())|set(sub[:,-1].tolist())
                    if len(b)==1 and list(b)[0]!=bg:
                        res.append((sub.tolist(),h,w))
    return res
res=rect_candidates(T,9)
print(len(res))
for s,h,w in sorted(res,key=lambda x:-x[1]*x[2])[:15]:
